mapper.select:
SELECT id, question_id, language, time_limit_ms, memory_limit_kb, output_limit_kb, confirmed
FROM tb_judge_language_limit
WHERE question_id = #{questionId}
  AND language = #{language}
  AND confirmed = TRUE

